	@override String get teamMemberJacopoDescription => 'Formato presso l\'Accademia di Astrologia Egizia fondata da Pascal Fabio Patruno, Jacopo è un astrologo geniale, capace di computare a mente la sinastria tra due persone, memorizzando gradi e pianeti di temi che ha visto una sola volta nella sua vita.';
	@override String get teamMemberJacopoRole => 'Astrologo';
